    10→class CompilerService {
    11→  constructor() {
    12→    this.tempDir = os.tmpdir();
    13→    this.compilers = {
    14→      c: new CCompiler(),
    15→      python: new PythonCompiler(),
    16→      go: new GoCompiler(),
    17→      rust: new RustCompiler(),
    18→      typescript: new TypeScriptCompiler(),
    19→      freelang: new FreeLangCompiler()
    20→    };
